.toggle-switch.active::after { transform: translateX(24px); }

.save-badge {
  background: var(--green);
  color: var(--white);
  padding: 4px 12px;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 700;
}

/* Team Size Slider */
.slider-container {
  max-width: 500px;
  margin: 0 auto 48px;
  text-align: center;
}
.slider-label {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: 12px;
}
.slider-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--dark);
  margin-bottom: 16px;
}
input[type="range"] {
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: var(--gray-200);
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(24,104,219,0.3);
}
input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: none;
  box-shadow: 0 2px 6px rgba(24,104,219,0.3);
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin: 48px 0;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.comparison-table th {
  text-align: left;
  padding: 16px 20px;
  font-weight: 600;
  background: var(--gray-50);
  border-bottom: 2px solid var(--gray-200);
  position: sticky;
  top: 72px;
}
.comparison-table th:first-child { min-width: 220px; }
.comparison-table th:not(:first-child) { text-align: center; min-width: 150px; }

.comparison-table td {
  padding: 14px 20px;
  border-bottom: 1px solid var(--gray-100);
  color: var(--gray-600);
}
.comparison-table td:not(:first-child) { text-align: center; }

.comparison-table .check { color: var(--green); font-weight: 700; font-size: 1.125rem; }
.comparison-table .dash { color: var(--gray-300); }

.comparison-table-collapsed { display: none; }
.comparison-table-collapsed.expanded { display: table-row-group; }

.expand-table-btn {
  display: block;
  margin: 24px auto;
  padding: 12px 28px;
  background: var(--gray-50);
  border: 2px solid var(--gray-200);
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--dark);
  cursor: pointer;
  transition: all var(--transition);
}
.expand-table-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--dark);
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question .icon {
  font-size: 1.25rem;
  transition: transform var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-question.active .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-answer.open {
  max-height: 500px;
  padding-bottom: 24px;
}
.faq-answer p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  padding: 20px 24px;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  transition: transform 0.3s ease;
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-banner p { font-size: 0.875rem; color: var(--gray-600); flex: 1; margin: 0; }
.cookie-banner-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}
.cookie-banner-actions button {
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.8125rem;
  transition: all var(--transition);
}
.cookie-accept {
  background: var(--primary);
  color: var(--white);
}
.cookie-accept:hover { background: var(--primary-dark); }
.cookie-reject {
  background: var(--gray-100);
  color: var(--gray-600);
}
.cookie-reject:hover { background: var(--gray-200); }
.cookie-manage {
  background: none;
  color: var(--primary);
  text-decoration: underline;
}
.cookie-manage:hover { color: var(--primary-dark); }

/* Cookie Modal */
.cookie-modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 10001;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.cookie-modal-overlay.active { opacity: 1; pointer-events: all; }

.cookie-modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px;
  max-width: 520px;
  width: 90%;
  box-shadow: var(--shadow-xl);
}
.cookie-modal h3 { margin-bottom: 8px; }
.cookie-modal > p { margin-bottom: 24px; font-size: 0.875rem; }

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-100);
}
.cookie-category-info h4 { font-size: 0.9375rem; margin-bottom: 2px; }
.cookie-category-info p { font-size: 0.8125rem; color: var(--gray-400); margin: 0; }

.cookie-toggle {
  position: relative;
  width: 44px;
  height: 24px;
  background: var(--gray-300);
  border-radius: 50px;
  cursor: pointer;
  transition: background var(--transition);
  flex-shrink: 0;
}
.cookie-toggle.active { background: var(--primary); }
.cookie-toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
}
.cookie-toggle.active::after { transform: translateX(20px); }
.cookie-toggle.disabled {
  background: var(--primary);
  opacity: 0.6;
  cursor: not-allowed;
}

.cookie-modal-actions {
  margin-top: 24px;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

/* Auth Pages */
.auth-page {
  min-height: 100vh;
  display: flex;
}
.auth-form-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px;
}
.auth-form {
  width: 100%;
  max-width: 400px;
}
.auth-form h1 {
  font-size: 2rem;
  margin-bottom: 32px;
}
.auth-social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 20px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--dark);
  margin-bottom: 12px;
  transition: all var(--transition);
  background: var(--white);
}
.auth-social-btn:hover {
  border-color: var(--gray-300);
  background: var(--gray-50);
}
.auth-social-btn svg { width: 20px; height: 20px; }

.auth-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 0.875rem;
}
.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.auth-input {
  width: 100%;
  padding: 14px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  transition: border-color var(--transition);
  margin-bottom: 16px;
}
.auth-input:focus {
  outline: none;
  border-color: var(--primary);
}

.auth-form .btn {
  width: 100%;
  margin-bottom: 16px;
}

.auth-footer {
  font-size: 0.8125rem;
  color: var(--gray-400);
  line-height: 1.5;
  margin-top: 16px;
}
.auth-footer a { color: var(--primary); }
.auth-footer a:hover { text-decoration: underline; }

.auth-sidebar {
  width: 480px;
  background: linear-gradient(135deg, #1868DB 0%, #6C3FE8 100%);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
}
.auth-sidebar blockquote {
  font-size: 1.25rem;
  line-height: 1.6;
  font-style: italic;
  margin-bottom: 24px;
}
.auth-sidebar .author { font-weight: 600; }
.auth-sidebar .role { opacity: 0.7; font-size: 0.875rem; }

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item .stat-number {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-item .stat-desc {
  font-size: 1rem;
  color: var(--gray-600);
}

/* Use Cases */
.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  transition: all var(--transition);
}
.use-case-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.use-case-icon {
  width: 48px;
  height: 48px;
  background: var(--purple-light);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 16px;
}
.use-case-card h4 { margin-bottom: 8px; }
.use-case-card p { font-size: 0.9375rem; }

/* Integrations */
.integrations-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
}
.integration-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 500;
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* AI Features */
.ai-feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 500;
}
.ai-feature-tag .new-badge {
  background: var(--accent);
  color: var(--white);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.625rem;
  font-weight: 700;
}

/* Benefits list */
.benefits-list {
  display: flex;
  flex-direction: column;
  gap: 32px;
}
.benefit-item {
  display: flex;
  gap: 20px;
}
.benefit-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.benefit-item h4 { margin-bottom: 4px; }
.benefit-item p { font-size: 0.9375rem; }

/* Security features */
.security-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.security-item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.security-icon {
  width: 40px;
  height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.125rem;
  flex-shrink: 0;
}
.security-item p { font-size: 0.9375rem; color: var(--gray-600); margin: 0; }

/* Feature Grid */
.features-grid-items {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.feature-grid-item {
  text-align: center;
  padding: 32px 20px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
}
.feature-grid-item:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow);
}
.feature-grid-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.feature-grid-item h4 {
  font-size: 0.9375rem;
  font-weight: 600;
}

/* Enterprise hero */
.hero-enterprise {
  padding: 120px 0 80px;
  background: linear-gradient(135deg, #f0f4ff 0%, #e8ecf8 100%);
  text-align: center;
}
.hero-enterprise h1 { margin-bottom: 20px; }
.hero-enterprise p { max-width: 600px; margin: 0 auto 32px; font-size: 1.125rem; }

/* Blog cards */
.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: all var(--transition);
}
.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.blog-card-image {
  height: 200px;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.blog-card-content {
  padding: 24px;
}
.blog-card-content h4 {
  margin-bottom: 8px;
  line-height: 1.4;
}
.blog-card-content p {
  font-size: 0.875rem;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 2.75rem; }
  h2 { font-size: 2rem; }
  .grid-4, .features-grid-items { grid-template-columns: repeat(2, 1fr); }
  .feature-block { grid-template-columns: 1fr; gap: 40px; }
  .feature-block.reverse { direction: ltr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .stats-grid { gap: 24px; }
  .stat-item .stat-number { font-size: 2.5rem; }
}

@media (max-width: 768px) {
  h1 { font-size: 2.25rem; }
  h2 { font-size: 1.75rem; }
  .section { padding: 64px 0; }
  .grid-2, .grid-3, .security-grid { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .mobile-menu-btn { display: flex; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .auth-sidebar { display: none; }
  .auth-form-container { padding: 24px; }
  .stats-grid { grid-template-columns: 1fr; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .cookie-banner-actions { justify-content: center; flex-wrap: wrap; }
  .comparison-table th, .comparison-table td { padding: 10px 12px; font-size: 0.8125rem; }
}

@media (max-width: 480px) {
  h1 { font-size: 1.875rem; }
  .container { padding: 0 16px; }
  .features-grid-items { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }
}
